/*
 * Standalone semantic check for the io_flush_timeouts loop change.
 *
 * This is NOT a build of the kernel. It faithfully mirrors the list primitives
 * from the target's include/linux/list.h (list_add_tail, list_del_init,
 * list_first_entry, list_for_each_entry_safe) and reproduces the pre-fix and
 * candidate forms of io_flush_timeouts together with the target io_kill_timeout
 * (which unlinks/frees only when hrtimer_try_to_cancel() != -1).
 *
 * Negative path: cancel fails (hrtimer_try_to_cancel() == -1).
 *   pre-fix: request is already unlinked by the flush loop.
 *   candidate: request is left linked for the normal cancelation path.
 * Positive path: cancel succeeds.
 *   both forms unlink exactly once and complete the request.
 */
#include <stdio.h>
#include <stddef.h>

struct list_head {
	struct list_head *next, *prev;
};

#define LIST_HEAD_INIT(name) { &(name), &(name) }
static inline void INIT_LIST_HEAD(struct list_head *list)
{
	list->next = list;
	list->prev = list;
}
static inline void __list_add(struct list_head *n, struct list_head *prev,
			      struct list_head *next)
{
	next->prev = n;
	n->next = next;
	n->prev = prev;
	prev->next = n;
}
static inline void list_add_tail(struct list_head *n, struct list_head *head)
{
	__list_add(n, head->prev, head);
}
static inline void __list_del(struct list_head *prev, struct list_head *next)
{
	next->prev = prev;
	prev->next = next;
}
static inline void list_del_init(struct list_head *entry)
{
	__list_del(entry->prev, entry->next);
	INIT_LIST_HEAD(entry);
}
static inline int list_empty(const struct list_head *head)
{
	return head->next == head;
}
#define container_of(ptr, type, member) \
	((type *)((char *)(ptr) - offsetof(type, member)))
#define list_entry(ptr, type, member) \
	container_of(ptr, type, member)
#define list_first_entry(ptr, type, member) \
	list_entry((ptr)->next, type, member)
#define list_next_entry(pos, member) \
	list_entry((pos)->member.next, typeof(*(pos)), member)
#define list_entry_is_head(pos, head, member) \
	(&(pos)->member == (head))
#define list_for_each_entry_safe(pos, n, head, member)			\
	for (pos = list_first_entry(head, typeof(*pos), member),	\
		n = list_next_entry(pos, member);			\
	     !list_entry_is_head(pos, head, member);			\
	     pos = n, n = list_next_entry(n, member))

struct io_kiocb {
	struct list_head timeout_list;
	int id;
};

static struct list_head ctx_timeout_list = LIST_HEAD_INIT(ctx_timeout_list);
static int cancel_result;	/* mimic hrtimer_try_to_cancel(): -1 == fail */
static int killed;

static void io_kill_timeout(struct io_kiocb *req)
{
	if (cancel_result != -1) {
		list_del_init(&req->timeout_list);
		killed++;
	}
}

/* pre-fix target form: unconditional unlink then kill */
static void flush_old(void)
{
	while (!list_empty(&ctx_timeout_list)) {
		struct io_kiocb *req = list_first_entry(&ctx_timeout_list,
						struct io_kiocb, timeout_list);
		list_del_init(&req->timeout_list);
		io_kill_timeout(req);
	}
}

/* candidate form: removal-safe walk, kill owns the unlink */
static void flush_new(void)
{
	struct io_kiocb *req, *tmp;

	list_for_each_entry_safe(req, tmp, &ctx_timeout_list, timeout_list)
		io_kill_timeout(req);
}

static int failures;

static void check(const char *name, int got, int want)
{
	printf("%-58s got=%d want=%d %s\n", name, got, want,
	       got == want ? "OK" : "FAIL");
	if (got != want)
		failures++;
}

int main(void)
{
	struct io_kiocb a = { .id = 1 }, b = { .id = 2 };

	/* Negative path: cancel fails, request must stay on the list. */
	INIT_LIST_HEAD(&ctx_timeout_list);
	INIT_LIST_HEAD(&a.timeout_list);
	list_add_tail(&a.timeout_list, &ctx_timeout_list);
	cancel_result = -1;
	killed = 0;
	flush_old();
	check("old, cancel=-1: request unlinked by flush", list_empty(&ctx_timeout_list), 1);
	check("old, cancel=-1: no completion", killed, 0);

	INIT_LIST_HEAD(&ctx_timeout_list);
	INIT_LIST_HEAD(&a.timeout_list);
	list_add_tail(&a.timeout_list, &ctx_timeout_list);
	cancel_result = -1;
	killed = 0;
	flush_new();
	check("new, cancel=-1: request left on list", list_empty(&ctx_timeout_list), 0);
	check("new, cancel=-1: no completion", killed, 0);
	check("new, cancel=-1: node still linked to head",
	      ctx_timeout_list.next == &a.timeout_list &&
	      a.timeout_list.next == &ctx_timeout_list, 1);

	/* Positive path: cancel succeeds, request removed exactly once. */
	INIT_LIST_HEAD(&ctx_timeout_list);
	INIT_LIST_HEAD(&a.timeout_list);
	list_add_tail(&a.timeout_list, &ctx_timeout_list);
	cancel_result = 1;
	killed = 0;
	flush_old();
	check("old, cancel=1: list emptied", list_empty(&ctx_timeout_list), 1);
	check("old, cancel=1: completed once", killed, 1);

	INIT_LIST_HEAD(&ctx_timeout_list);
	INIT_LIST_HEAD(&a.timeout_list);
	list_add_tail(&a.timeout_list, &ctx_timeout_list);
	cancel_result = 1;
	killed = 0;
	flush_new();
	check("new, cancel=1: list emptied", list_empty(&ctx_timeout_list), 1);
	check("new, cancel=1: completed once", killed, 1);

	/* Removal-safety: two entries, both cancel failures, no hang/corruption. */
	INIT_LIST_HEAD(&ctx_timeout_list);
	INIT_LIST_HEAD(&a.timeout_list);
	INIT_LIST_HEAD(&b.timeout_list);
	list_add_tail(&a.timeout_list, &ctx_timeout_list);
	list_add_tail(&b.timeout_list, &ctx_timeout_list);
	cancel_result = -1;
	killed = 0;
	flush_new();
	check("new, 2 entries cancel=-1: both stay linked", list_empty(&ctx_timeout_list), 0);
	check("new, 2 entries cancel=-1: walk advanced", killed, 0);
	check("new, 2 entries cancel=-1: a still linked", a.timeout_list.next != &a.timeout_list, 1);
	check("new, 2 entries cancel=-1: b still linked", b.timeout_list.next != &b.timeout_list, 1);

	printf(failures ? "\nRESULT: FAIL (%d)\n" : "\nRESULT: PASS\n", failures);
	return failures ? 1 : 0;
}

